def backfill_audit_metadata(apps, schema_editor):
    """Populate new audit fields without inventing historical certainty.

    Existing entries get a snapshot of their current values (the best evidence
    still available). Resolved entries are labelled ``legacy`` so reports can
    distinguish old decisions from current scoring. Existing notifications keep
    their in-app meaning but are marked ``skipped`` because email was already
    handled synchronously before the outbox existed.
    """

    CrushEntry = apps.get_model("campus", "CrushEntry")
    Notification = apps.get_model("campus", "Notification")

    batch = []
    for entry in CrushEntry.objects.filter(original_payload={}).iterator(
        chunk_size=500
    ):
        entry.original_payload = {
            "full_name": entry.full_name,
            "roll_number": entry.roll_number,
            "college_id": entry.college_id,
            "course": entry.course,
            "year": entry.year,
            "section": entry.section,
            "department": entry.department,
            "nickname": entry.nickname,
        }
        if entry.identity_status == "resolved":
            entry.resolution_scoring_version = "legacy"
        batch.append(entry)
        if len(batch) >= 500:
            CrushEntry.objects.bulk_update(
                batch,
                ["original_payload", "resolution_scoring_version"],
            )
            batch = []
    if batch:
        CrushEntry.objects.bulk_update(
            batch,
            ["original_payload", "resolution_scoring_version"],
        )

    Notification.objects.update(email_status="skipped")


